package com.taller.portal.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="usuarios")
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false,length=80) public String nombre; @Column(nullable=false,unique=true,length=140) public String email; @Column(nullable=false,unique=true,length=25) public String celular; @Column(nullable=false) public String passwordHash; @ManyToOne(optional=false) @JoinColumn(name="rol_id",nullable=false) public Role rol; @ManyToOne @JoinColumn(name="taller_id") public Taller taller; @Column(nullable=false) public boolean activo=true; @Column(nullable=false) public boolean emailVerificado=false; public LocalDateTime creadoEn=LocalDateTime.now(); public LocalDateTime ultimoAcceso; }
